from h import *

nueva('lepista-nuda', cient='Lepista nuda', sin=['Collybia nuda', 'Clitocybe nuda', 'Agaricus nudus'], es=[], eu=['ziza hankaurdin', 'oin-urdin'], grupo='laminar', clase='sin_datos', cand=True,
  nomen='El nombre científico varía según la fuente: Lepista nuda, Clitocybe nuda y Collybia nuda se refieren a la misma seta.',
  nota='Wikipedia la da como buena comestible, pero se confunde con Cortinarius azulados o violáceos, muchos de ellos venenosos. La Wikipedia en euskera avisa de que puede sentar mal a algunos estómagos.',
  clave='Seta lila-violeta con olor muy característico y esporada blanca-rosada. Si tiene restos de velo bajo el sombrero y la esporada sale pardo-óxido, es un Cortinarius: venenoso.',
  mirar=[q('sombrero', 'Lila a rosa-púrpura', '4–15 cm. Los jóvenes son más claros y convexos; los maduros, más oscuros y planos. Algunos ejemplares norteamericanos tiran a beige pero conservan tonos violeta en el pie y las láminas.'),
         q('himenio', 'Láminas pegadas al pie', 'De color lila. Se unen al pie, que es corto y robusto.'),
         q('pie', 'Corto, grueso y violáceo', '2–6 cm de alto y 1–2,5 cm de ancho, a veces más ancho en la base.'),
         q('olor', 'Olor muy característico', 'Muy marcado: un autor lo comparó con el de zumo de naranja congelado. Con la esporada, sirve para distinguirla.'),
         q('esporada', 'Esporada blanca a rosa pálido', 'Blanca a rosa pálido. La de los Cortinarius es pardo-óxido tras unas horas sobre papel blanco.'),
         q('habitat', 'Suelos con humus, tardía', 'Saprótrofa, sobre suelos con mucho humus. Es una de las setas más tardías del otoño y llega a principios del invierno, y a veces sale en primavera. A veces forma grandes grupos o círculos.')],
  conf=[c(None, 'Cortinarius violáceos o azulados (p. ej. C. camphoratus)', 'Muchos pueden ser venenosos. Los Cortinarius suelen tener restos de velo bajo el sombrero y una marca en forma de anillo en el pie; su esporada es pardo-óxido tras varias horas sobre papel blanco, y sus esporas pardas suelen espolvorear el pie y lo que hay debajo.', 'alta'),
        c(None, 'Otras setas violáceas pequeñas', 'También se parece a Collybia brunneocephala, Clitocybe tarda, Laccaria amethysteo-occidentalis y Lepista subconnexa (Wikipedia).', 'baja')],
  hab=['mixto', 'frondosas', 'coniferas'], habt='Saprótrofa: crece sobre suelos con mucho humus, en bosques; a veces forma grandes grupos o círculos. Muy tardía: de finales de otoño a principios de invierno.',
  rec=dict(acc='cortar', txt='Corte limpio por la base. Tamaño mínimo que recomienda La Rioja: 4 cm de sombrero. Haz siempre la esporada y huele la seta: el olor y la esporada son lo que la separa de los Cortinarius.'),
  esp='blanca a rosa pálido',
  cur=['Pierre Bulliard la describió en 1790 como «Agaricus nudus» y escribió que era común en los bosques todo el año.',
       'En Australia, un macho joven de ave sedera (satin bowerbird) usó setas de esta especie para decorar su nido: estas aves coleccionan objetos azules.',
       'Se cultiva en Gran Bretaña, Países Bajos y Francia, aunque se dice que las cultivadas saben menos que las silvestres.'],
  meses=[10, 11, 12], mnota='Final del otoño y principios del invierno; a veces en primavera.', wp=['lepista-nuda'], rioja=True)

nueva('armillaria-mellea', cient='Armillaria mellea', sin=['Agaricus melleus'], es=['hongo de miel'], eu=['enbor-ziza'], grupo='laminar', clase='sin_datos', cand=True,
  nota='No es para principiantes: crece en madera y se confunde con la Galerina marginata (mortal). El catálogo inicial indica que Aranzadi no la recomienda. Wikipedia: comestible joven y muy cocinada; algunas matas dan problemas digestivos.',
  clave='Mata de setas color miel sobre tocones o base de troncos, con anillo ancho y láminas blancas. Se parece a la Galerina mortal: aquí la esporada es BLANCA, en la Galerina pardo-óxido.',
  mirar=[q('sombrero', 'Color miel, muy variable', '3–15 cm. Liso, convexo y luego aplanado, a menudo con mamelón central; pegajoso con humedad. Suele ser color miel pero cambia mucho, y a veces lleva unas escamitas oscuras y pelosas cerca del centro.'),
         q('himenio', 'Láminas blancas, separadas', 'Blancas al principio, a veces rosa-amarillentas o descoloridas con la edad. Anchas y bastante espaciadas; unidas al pie en ángulo recto o algo decurrentes.'),
         q('pie', 'Fibroso, en mata y con base oscura', '5–20 cm, cilíndrico, afilado en la base, donde se junta con los pies de los demás del grupo. Blanquecino arriba, pardo-amarillento abajo y a menudo con la base muy oscura. Primero esponjoso, luego hueco.'),
         q('anillo', 'Anillo ancho, persistente', 'Ancho y parecido a una piel, con el borde aterciopelado y pelusa amarillenta por debajo.'),
         q('carne', 'Blanquecina, dulzona con amargor', 'Olor y sabor algo dulces con un toque de amargor.'),
         q('habitat', 'Mata sobre tocón o base de tronco', 'Parásita de muchas frondosas; sale en grupos densos en la base de troncos o tocones. También en jardines, parques y viñedos.')],
  conf=[c('hypholoma-fasciculare', 'Hypholoma fasciculare', 'Tóxica: también en mata sobre madera, pero con tonos amarillo azufre, láminas que se vuelven verdes y sabor muy amargo. La Wikipedia en español dice que un principiante la confunde con el hongo de miel.', 'alta'),
        c('galerina-marginata', 'Galerina marginata', 'Las dos crecen en madera y tienen anillo; la esporada las separa: blanca en Armillaria, pardo-óxido en Galerina. Por eso no se recomienda recoger armilarias siendo novato.', 'alta')],
  hab=['frondosas', 'madera', 'arbol_vivo', 'parque'], habt='Parásita sobre muchas frondosas; sale en grupos densos en la base de troncos o en tocones. Prefiere suelos húmedos y fríos. Aguanta temperaturas extremas, incluso incendios, protegida por el suelo. Se ve también en parques, jardines y viñedos.',
  rec=dict(acc='dejar', txt='Para un principiante: déjala o compruébala con alguien que sepa. Wikipedia: se recoge joven, se cocina a fondo y se descartan los pies duros; algunas matas (p. ej. sobre ciertas especies de árbol) dan problemas digestivos. Escaldarla quita el amargor.'),
  esp='blanca',
  cur=['Daña mucho al árbol que parasita y acaba por secarlo (Wikipedia en euskera).',
       'Según la Wikipedia en euskera, los rizomorfos (las «raíces» oscuras) de la seta son fosforescentes en la oscuridad.',
       'Fue descrita por Martin Vahl en 1790 como Agaricus melleus.',
       'Produce compuestos citotóxicos llamados meleolidas.'],
  meses=[], mnota=None, wp=['armillaria-mellea'], rioja=False)

nueva('pleurotus-ostreatus', cient='Pleurotus ostreatus', sin=['Agaricus ostreatus'], es=['gírgola', 'seta de ostra', 'champiñón ostra', 'pleuroto ostra'], eu=['belarri landu'], grupo='laminar', clase='sin_datos', cand=True,
  clave='Setas en forma de abanico u ostra, escalonadas sobre troncos de frondosas (sobre todo haya), con láminas blancas que bajan por el pie y olor a almendra amarga.',
  mirar=[q('sombrero', 'Abanico u ostra', '2–30 cm. Blanco, gris o pardo; el borde está enrollado de joven y luego es liso y ondulado.'),
         q('himenio', 'Láminas decurrentes', 'Blanquecinas, a veces amarillentas; bajan por el pie si lo hay.'),
         q('pie', 'Casi sin pie', 'Si existe, mide hasta 4 cm y sale de lado, descentrado, pegado a la madera.'),
         q('carne', 'Blanca y firme', 'Blanca, de grosor variable.'),
         q('olor', 'Agridulce, a almendra amarga', 'Aroma de benzaldehído o almendras amargas.'),
         q('esporada', 'Esporada blanca a gris-lila', 'Blanca a gris-lila; se ve mejor sobre fondo oscuro.'),
         q('habitat', 'En madera de frondosas', 'Sobre madera, sobre todo de frondosas y en particular de haya; crece sobre árboles moribundos.')],
  conf=[c('omphalotus-illudens', 'Omphalotus (grupo)', 'Tóxicos y también sobre madera. Wikipedia cita O. nidiformis (Australia) y O. olivascens (América del Norte) como parecidos tóxicos.', 'alta'),
        c(None, 'Lentinellus', 'Algunos son tóxicos y parecidos, pero tienen las láminas con el borde irregular y el sombrero finamente peloso.', 'media'),
        c(None, 'Otras setas de madera en repisa', 'También se parece a P. columbinus, P. cornucopiae, Hohenbuehelia petaloides, Phyllotopsis nidulans y Pleurocybella porrigens.', 'baja')],
  hab=['frondosas', 'hayedo', 'madera'], habt='Saprótrofa y descomponedora primaria de madera, sobre todo de frondosas y de haya en particular. No es parásita: sale sobre árboles que se mueren por otras causas.',
  rec=dict(acc='cortar', txt='Es una seta de madera: corta con navaja en la base de la mata. Comprueba el olor a almendra amarga y que crece sobre madera.'),
  esp='blanca a gris-lila',
  cur=['Su cultivo comercial empezó en Alemania durante la Primera Guerra Mundial, como medida de subsistencia; hoy se cultiva en todo el mundo.',
       'El nombre viene de su forma: «pleurotus» es «oreja de lado» (el pie sale de lado) y «ostreatus» recuerda a la ostra.',
       'Es una especie que descompone madera (podredumbre blanca) y devuelve minerales al ecosistema.',
       'En la cocina checa, polaca y eslovaca se usa en sopas y guisos como sustituto de la carne; es un manjar en Japón, Corea y China.'],
  meses=[], mnota=None, wp=['pleurotus-ostreatus'], rioja=False)

nueva('russula-cyanoxantha', cient='Russula cyanoxantha', sin=[], es=['carbonera'], eu=['urritx', 'gibelurdin', 'gibel-perretxiko'], grupo='laminar', clase='sin_datos', cand=True,
  clave='Rúsula de colores muy variables (violeta, verde, gris…, nunca roja) con láminas blancas, flexibles y grasientas al tacto que no se rompen.',
  mirar=[q('sombrero', 'Violeta, verde, gris… nunca rojo', '4–18 cm. Convexo y luego aplanado; verdoso a pardo brillante, muy variable. En la Wikipedia en euskera: casi siempre morado oscuro o azulado, pero puede ser verde oscuro o gris violáceo, y nunca es rojo.'),
         q('himenio', 'Láminas flexibles y grasientas', 'Blancas a crema, a veces bifurcadas. Son el rasgo clave: al tacto resultan grasientas, flexibles y no se rompen, a diferencia de casi todas las demás rúsulas.'),
         q('pie', 'Blanco puro', '2,5–12 cm de alto y 1–5 cm de ancho, blanco.'),
         q('carne', 'Menos dura, sabor a nuez', 'Menos dura que la de otras rúsulas comestibles; sabor suave a nuez. A menudo la infestan gusanos.'),
         q('esporada', 'Esporada blanca', 'Blanca.'),
         q('habitat', 'Hayedos y frondosas', 'Suelos algo ácidos pero ricos. Micorrícica; sobre todo en hayedos y a menudo en bosques caducifolios o mixtos.')],
  conf=[c('amanita-phalloides', 'Amanita phalloides (rúsulas verdes)', 'Si el sombrero tiene tonos verdes, mira la base: la Amanita mortal lleva anillo y volva y la rúsula no.', 'alta'),
        c('russula-emetica', 'Russula emetica', 'La rúsula picante y emética suele ser roja; la carbonera nunca lo es.', 'media'),
        c(None, 'Russula virescens', 'Tiene la cutícula cuarteada y verdosa con reflejos rosados (Wikipedia en español).', 'baja'),
        c(None, 'R. olivacea, R. aeruginea, R. versicolor, R. grisea', 'R. olivacea da esporada amarilla; R. aeruginea es verdosa con láminas bifurcadas; R. versicolor tiene las láminas amarillentas sin bifurcar; R. grisea es más gris-azulada con láminas crema claro.', 'baja')],
  hab=['hayedo', 'frondosas', 'mixto'], habt='Suelos ligeramente ácidos pero ricos en nutrientes. Como todas las rúsulas es micorrícica; la encuentras sobre todo en hayedos, y a menudo en bosques de frondosas o mixtos.',
  rec=dict(acc='cortar', txt='Corte limpio por la base. Quizá solo las europeas sean de verdad R. cyanoxantha (Wikipedia). Revisa si tiene gusanos.'),
  esp='blanca',
  cur=['«Carbonera» (charcoal burner en inglés) es el nombre común que da la Wikipedia en español.',
       'Wikipedia sugiere que quizá solo los ejemplares europeos son de verdad esta especie.'],
  meses=[], mnota=None, wp=['russula-cyanoxantha'], rioja=False)
